import Foundation

/// Text rules exactly as .NET applies them, for code ported from the C# core (thumbfree-windows `src/ThumbFree.Core`).
/// The shared vectors in tests/vectors were generated by that C# code, so a Swift port must treat whitespace, letters
/// and case the way .NET does, not the way Swift's `Character` (grapheme clusters, full case mapping) does. These work
/// on Unicode scalars, the closest Swift unit to .NET's UTF-16 `char` for this text. Comparisons are ordinal, like C#'s
/// `==`: Swift's `==` and `hasPrefix` treat canonically equivalent strings ("é" and "e\u{301}") as equal.
enum DotNet {
    // MARK: Characters

    /// `char.IsWhiteSpace`: Unicode's White_Space property is the same set (Zs, Zl, Zp, U+0009–U+000D, U+0085).
    static func isWhiteSpace(_ scalar: Unicode.Scalar) -> Bool { scalar.properties.isWhitespace }

    /// `char.IsLetter`: the Lu, Ll, Lt, Lm and Lo categories.
    static func isLetter(_ scalar: Unicode.Scalar) -> Bool {
        switch scalar.properties.generalCategory {
        case .uppercaseLetter, .lowercaseLetter, .titlecaseLetter, .modifierLetter, .otherLetter: return true
        default: return false
        }
    }

    /// `char.IsDigit`: decimal digits (Nd) only, not ² or ½.
    static func isDigit(_ scalar: Unicode.Scalar) -> Bool { scalar.properties.generalCategory == .decimalNumber }

    /// `char.IsLetterOrDigit`.
    static func isLetterOrDigit(_ scalar: Unicode.Scalar) -> Bool { isLetter(scalar) || isDigit(scalar) }

    /// `char.IsLower`: the Ll category.
    static func isLower(_ scalar: Unicode.Scalar) -> Bool { scalar.properties.generalCategory == .lowercaseLetter }

    /// `char.IsUpper`: the Lu category.
    static func isUpper(_ scalar: Unicode.Scalar) -> Bool { scalar.properties.generalCategory == .uppercaseLetter }

    /// `char.ToUpperInvariant`: the simple (one-to-one) uppercase mapping, so "ß" stays "ß" instead of becoming "SS".
    /// Where the full mapping adds a letter ("ᾀ" → "ἈΙ"), the simple one is the one-letter title case ("ᾈ"). As in
    /// .NET, the Turkish dotless "ı" keeps its case.
    static func toUpperInvariant(_ scalar: Unicode.Scalar) -> Unicode.Scalar {
        if scalar == "\u{131}" {
            return scalar
        }

        let upper = scalar.properties.uppercaseMapping.unicodeScalars
        if upper.count == 1 {
            return upper.first!
        }

        let title = scalar.properties.titlecaseMapping.unicodeScalars
        return title.count == 1 ? title.first! : scalar
    }

    /// `char.ToLowerInvariant`: the simple lowercase mapping ("İ", whose full mapping is two scalars, keeps its case).
    static func toLowerInvariant(_ scalar: Unicode.Scalar) -> Unicode.Scalar {
        let lower = scalar.properties.lowercaseMapping.unicodeScalars
        return lower.count == 1 ? lower.first! : scalar
    }

    /// The case `StringComparison.OrdinalIgnoreCase` compares: the simple uppercase, except that "ſ" isn't "S".
    private static func ordinalUpper(_ scalar: Unicode.Scalar) -> Unicode.Scalar {
        scalar == "\u{17F}" ? scalar : toUpperInvariant(scalar)
    }

    // MARK: Case

    /// `string.ToUpperInvariant()`.
    static func upperInvariant(_ text: String) -> String { string(text.unicodeScalars.map { toUpperInvariant($0) }) }

    /// `string.ToLowerInvariant()`.
    static func lowerInvariant(_ text: String) -> String { string(text.unicodeScalars.map { toLowerInvariant($0) }) }

    /// `char.ToUpperInvariant(s[0]) + s[1..]`.
    static func upperFirst(_ text: String) -> String { mapFirst(text) { toUpperInvariant($0) } }

    /// `char.ToLowerInvariant(s[0]) + s[1..]`.
    static func lowerFirst(_ text: String) -> String { mapFirst(text) { toLowerInvariant($0) } }

    /// The first letter in upper case when it's a lower-case letter (the C# core's `Capitalize`).
    static func capitalize(_ text: String) -> String {
        guard let first = text.unicodeScalars.first, isLower(first) else { return text }
        return upperFirst(text)
    }

    private static func mapFirst(_ text: String, _ transform: (Unicode.Scalar) -> Unicode.Scalar) -> String {
        guard let first = text.unicodeScalars.first else { return text }
        var scalars = String.UnicodeScalarView()
        scalars.append(transform(first))
        scalars.append(contentsOf: text.unicodeScalars.dropFirst())
        return String(scalars)
    }

    // MARK: Trimming and splitting

    /// `string.IsNullOrWhiteSpace`.
    static func isNullOrWhiteSpace(_ text: String?) -> Bool {
        guard let text else { return true }
        return text.unicodeScalars.allSatisfy { isWhiteSpace($0) }
    }

    /// `string.Trim()`.
    static func trim(_ text: String) -> String { trimEnd(trimStart(text)) }

    /// `string.Trim(params char[])`.
    static func trim(_ text: String, _ characters: Set<Unicode.Scalar>) -> String {
        trimEnd(trimStart(text, characters), characters)
    }

    /// `string.TrimStart()`.
    static func trimStart(_ text: String) -> String { trimStart(text) { isWhiteSpace($0) } }

    /// `string.TrimStart(params char[])`.
    static func trimStart(_ text: String, _ characters: Set<Unicode.Scalar>) -> String {
        trimStart(text) { characters.contains($0) }
    }

    static func trimStart(_ text: String, while drop: (Unicode.Scalar) -> Bool) -> String {
        var scalars = Substring(text).unicodeScalars[...]
        while let first = scalars.first, drop(first) { scalars = scalars.dropFirst() }
        return String(String.UnicodeScalarView(scalars))
    }

    /// `string.TrimEnd()`.
    static func trimEnd(_ text: String) -> String { trimEnd(text) { isWhiteSpace($0) } }

    /// `string.TrimEnd(params char[])`: drops trailing scalars that are in `characters`.
    static func trimEnd(_ text: String, _ characters: Set<Unicode.Scalar>) -> String {
        trimEnd(text) { characters.contains($0) }
    }

    static func trimEnd(_ text: String, while drop: (Unicode.Scalar) -> Bool) -> String {
        var scalars = Substring(text).unicodeScalars[...]
        while let last = scalars.last, drop(last) { scalars = scalars.dropLast() }
        return String(String.UnicodeScalarView(scalars))
    }

    /// `string.Split((char[])null, RemoveEmptyEntries | TrimEntries)`: the runs of text between whitespace.
    static func words(_ text: String) -> [String] {
        var words: [String] = []
        var current = String.UnicodeScalarView()
        for scalar in text.unicodeScalars {
            if isWhiteSpace(scalar) {
                if !current.isEmpty {
                    words.append(String(current))
                    current = String.UnicodeScalarView()
                }
            } else {
                current.append(scalar)
            }
        }

        if !current.isEmpty { words.append(String(current)) }
        return words
    }

    /// `string.Split(params char[])`: the pieces between separators, empty ones included.
    static func split(_ text: String, _ separators: Set<Unicode.Scalar>) -> [String] {
        var pieces: [String] = []
        var current = String.UnicodeScalarView()
        for scalar in text.unicodeScalars {
            if separators.contains(scalar) {
                pieces.append(String(current))
                current = String.UnicodeScalarView()
            } else {
                current.append(scalar)
            }
        }

        pieces.append(String(current))
        return pieces
    }

    /// `string.Split(["\r\n", "\n", "\r"], StringSplitOptions.None)`: the lines, however they end.
    static func lines(_ text: String) -> [String] { split(replace(replace(text, "\r\n", "\n"), "\r", "\n"), ["\n"]) }

    // MARK: Ordinal comparison

    /// `a == b` in C#: the same scalars.
    static func ordinalEquals(_ a: String, _ b: String) -> Bool { a.utf8.elementsEqual(b.utf8) }

    /// `a.SequenceEqual(b)` for strings.
    static func sequenceEqual(_ a: [String], _ b: [String]) -> Bool {
        a.count == b.count && zip(a, b).allSatisfy { ordinalEquals($0, $1) }
    }

    /// `text.StartsWith(prefix, StringComparison.Ordinal)`.
    static func startsWith(_ text: String, _ prefix: String) -> Bool { text.utf8.starts(with: prefix.utf8) }

    /// `text.EndsWith(suffix, StringComparison.Ordinal)`.
    static func endsWith(_ text: String, _ suffix: String) -> Bool {
        text.utf8.reversed().starts(with: suffix.utf8.reversed())
    }

    /// `text[prefix.Length..]`, for a `prefix` that `startsWith` found.
    static func dropPrefix(_ text: String, _ prefix: String) -> String {
        String(text[text.utf8.index(text.startIndex, offsetBy: prefix.utf8.count)...])
    }

    /// `text.Contains(value, StringComparison.Ordinal)`.
    static func contains(_ text: String, _ value: String) -> Bool {
        let source = Array(text.unicodeScalars)
        let target = Array(value.unicodeScalars)
        if target.isEmpty {
            return true
        }

        guard source.count >= target.count else { return false }
        return (0...(source.count - target.count)).contains { source[$0..<($0 + target.count)].elementsEqual(target) }
    }

    /// `text.Replace(old, new)`: every occurrence, left to right.
    static func replace(_ text: String, _ old: String, _ new: String) -> String {
        let source = Array(text.unicodeScalars)
        let target = Array(old.unicodeScalars)
        guard !target.isEmpty else { return text }
        var out = String.UnicodeScalarView()
        var i = 0
        while i < source.count {
            if i + target.count <= source.count && source[i..<(i + target.count)].elementsEqual(target) {
                out.append(contentsOf: new.unicodeScalars)
                i += target.count
            } else {
                out.append(source[i])
                i += 1
            }
        }

        return String(out)
    }

    /// `string.Equals(a, b, StringComparison.OrdinalIgnoreCase)`: scalar by scalar after the simple uppercase mapping.
    static func equalsOrdinalIgnoreCase(_ a: String, _ b: String) -> Bool {
        ordinalIgnoreCase(a) == ordinalIgnoreCase(b)
    }

    /// A key for a `Set` or `Dictionary` that compares as `StringComparer.Ordinal` does.
    static func ordinal(_ text: String) -> [Unicode.Scalar] { Array(text.unicodeScalars) }

    /// A key for a `Set` or `Dictionary` that compares as `StringComparer.OrdinalIgnoreCase` does.
    static func ordinalIgnoreCase(_ text: String) -> [Unicode.Scalar] { text.unicodeScalars.map { ordinalUpper($0) } }

    // MARK: Numbers and order

    /// `(int)value` in .NET 9 and later: toward zero, saturating at the `int` range, and 0 for NaN.
    static func toInt32(_ value: Double) -> Int {
        if value.isNaN {
            return 0
        }

        if value >= Double(Int32.max) {
            return Int(Int32.max)
        }

        return value <= Double(Int32.min) ? Int(Int32.min) : Int(value)
    }

    /// LINQ's `OrderBy`: a stable sort, so items with the same key keep their order.
    static func orderBy<T, Key: Comparable>(_ items: [T], _ key: (T) -> Key) -> [T] {
        items.enumerated()
            .sorted { a, b in
                let first = key(a.element)
                let second = key(b.element)
                return first < second || (!(second < first) && a.offset < b.offset)
            }
            .map { $0.element }
    }

    /// LINQ's `OrderByDescending`, stable as well.
    static func orderByDescending<T, Key: Comparable>(_ items: [T], _ key: (T) -> Key) -> [T] {
        items.enumerated()
            .sorted { a, b in
                let first = key(a.element)
                let second = key(b.element)
                return second < first || (!(first < second) && a.offset < b.offset)
            }
            .map { $0.element }
    }

    /// A string of `scalars`.
    static func string<S: Sequence>(_ scalars: S) -> String where S.Element == Unicode.Scalar {
        var view = String.UnicodeScalarView()
        view.append(contentsOf: scalars)
        return String(view)
    }
}
